const keys={},clock=new THREE.Clock(),playerState={hp:100,maxHp:100,mp:70,maxMp:70,gold:24,xp:0,level:1,spell:0,contract:false,kills:0,won:false,invuln:0};
let started=false,modal=false,toastTimer=0,attackCooldown=0,castCooldown=0,yaw=0,pitch=.16,interactTarget=null;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
