function updateHud(){const s=playerState;$('#hpText').textContent=`${Math.ceil(s.hp)} / ${s.maxHp}`;$('#mpText').textContent=`${Math.floor(s.mp)} / ${s.maxMp}`;$('#hpBar').style.width=`${100*s.hp/s.maxHp}%`;$('#mpBar').style.width=`${100*s.mp/s.maxMp}%`;$('#gold').textContent=s.gold;$('#level').textContent=String(s.level).padStart(2,'0');for(let i=0;i<3;i++)$('#spell'+i).classList.toggle('active',s.spell===i);if(s.contract){$('#questTitle').textContent=s.won?'Contrato concluído!':'Uma rua mais segura';$('#questDesc').textContent=s.won?'Os moradores podem voltar a caminhar sem medo. Fale com a escrivã para receber outro trabalho.':'Ecos sombrios rondam os arcos ao norte. Derrote-os e volte à praça.';$('#questCount').textContent=s.won?'Recompensa recebida · bom trabalho!':`${s.kills} / 3 Ecos derrotados`;$('#progress').style.width=`${Math.min(100,s.kills/3*100)}%`}}
