updateHud();
function openJob(){modal=true;$('#jobmodal').style.display='grid';document.exitPointerLock?.()}
function closeJob(){modal=false;$('#jobmodal').style.display='none'}
$('#startBtn').addEventListener('click',()=>{started=true;$('#intro').style.opacity='0';setTimeout(()=>$('#intro').style.display='none',560);$('#hud').style.display='block';renderer.domElement.requestPointerLock?.();notice('A escrivã tem um contrato para você.')});
$('#acceptJob').addEventListener('click',()=>{const s=playerState;if(s.won){s.kills=0;s.won=false;for(const e of enemies){e.userData.alive=true;e.userData.hp=e.userData.max;e.visible=true;e.position.copy(e.userData.home)}}s.contract=true;closeJob();updateHud();notice('Contrato aceito — procure os Ecos ao norte!')});
$('#declineJob').addEventListener('click',closeJob);
document.addEventListener('pointerlockchange',()=>{});
document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement&&!modal){yaw-=e.movementX*.0022;pitch=clamp(pitch+e.movementY*.0018,-.25,.65)}});
document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyE')interact();if(e.code==='Escape'&&modal)closeJob();if(e.code==='Digit1'||e.code==='Digit2'||e.code==='Digit3'){playerState.spell=Number(e.code.slice(-1))-1;updateHud()}if(e.code==='Space'||e.code==='Enter')cast()});
document.addEventListener('keyup',e=>keys[e.code]=false);
renderer.domElement.addEventListener('click',()=>{if(started&&!modal&&document.pointerLockElement!==renderer.domElement)renderer.domElement.requestPointerLock?.();else if(started&&!modal)cast()});
