function isBlocked(x,z){if(Math.abs(x)>46||Math.abs(z)>46)return true;const blocks=[[-16,-13,7.5,6], [14,-16,8,6.5],[-16,14,7.5,7],[16,15,8.5,6.5],[-34,-12,8,7],[34,-12,8,7],[-34,15,8.5,6.5],[35,16,8,7]];return blocks.some(([bx,bz,rx,rz])=>Math.abs(x-bx)<rx&&Math.abs(z-bz)<rz)}
function interactCheck(){const dBoard=Math.hypot(player.position.x+2.2,player.position.z-1.6);const dClerk=Math.hypot(player.position.x+2.2,player.position.z-2);if(dBoard<3.4){interactTarget='board';$('#interactionText').textContent=playerState.won?'Ver novo contrato':'Ver contratos'}else if(dClerk<2.8){interactTarget='clerk';$('#interactionText').textContent='Falar com a escrivã'}else interactTarget=null;$('#interaction').classList.toggle('show',!!interactTarget&&!modal)}
function update(dt,time){if(!started||modal)return;const s=playerState;castCooldown=Math.max(0,castCooldown-dt);attackCooldown=Math.max(0,attackCooldown-dt);s.invuln=Math.max(0,s.invuln-dt);s.mp=Math.min(s.maxMp,s.mp+dt*2.7);
let mx=0,mz=0;if(keys.KeyW||keys.ArrowUp)mz-=1;if(keys.KeyS||keys.ArrowDown)mz+=1;if(keys.KeyA||keys.ArrowLeft)mx-=1;if(keys.KeyD||keys.ArrowRight)mx+=1;const len=Math.hypot(mx,mz);if(len){mx/=len;mz/=len;const speed=keys.ShiftLeft||keys.ShiftRight?10:5.7;const fx=Math.sin(yaw),fz=-Math.cos(yaw),rx=Math.cos(yaw),rz=Math.sin(yaw);const dx=(fx*(-mz)+rx*mx)*speed*dt,dz=(fz*(-mz)+rz*mx)*speed*dt;let nx=player.position.x+dx,nz=player.position.z+dz;if(!isBlocked(nx,player.position.z))player.position.x=nx;if(!isBlocked(player.position.x,nz))player.position.z=nz;player.rotation.y=yaw;if(keys.ShiftLeft||keys.ShiftRight)s.invuln=.22}
// Soft camera follow and shoulder perspective
const wanted=new THREE.Vector3(player.position.x+Math.sin(yaw)*8,player.position.y+4.3+pitch*4,player.position.z+Math.cos(yaw)*8);camera.position.lerp(wanted,1-Math.exp(-dt*5));camera.lookAt(player.position.x,player.position.y+1.25,player.position.z);
// Enemy pursuit and contact damage
if(s.contract&&!s.won){for(const e of enemies){if(!e.userData.alive)continue;const dir=new THREE.Vector3().subVectors(player.position,e.position);const dist=dir.length();e.position.y=.12+Math.sin(time*2.8+e.position.x)*.12;e.rotation.y=Math.atan2(dir.x,dir.z);if(dist>2.25&&dist<25){dir.normalize();e.position.x+=dir.x*dt*1.35;e.position.z+=dir.z*dt*1.35}else if(dist<=2.25){e.userData.attack-=dt;if(e.userData.attack<=0){e.userData.attack=1.15;if(s.invuln<=0){s.hp=Math.max(0,s.hp-9);updateHud();if(s.hp<=0){s.hp=s.maxHp;s.mp=Math.max(0,s.mp-15);player.position.set(0,0,5);notice('Você foi salvo pela magia da cidade. Vitalidade restaurada.')}else notice('Um Eco atingiu você!')}}}}}
for(let i=bolts.length-1;i>=0;i--){const b=bolts[i];b.t+=dt*2.8;b.mesh.position.lerpVectors(b.from,b.to,Math.min(1,b.t));b.mesh.rotation.x+=dt*7;if(b.t>=1){scene.remove(b.mesh);b.mesh.geometry.dispose();b.mesh.material.dispose();bolts.splice(i,1)}}
player.visible=s.invuln<=0||Math.floor(time*15)%2===0;
for(const l of lamps)l.children.find(o=>o.isPointLight).intensity=7.5+Math.sin(time*2+l.position.x)*.4;
interactCheck();if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show')}
}
function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.04),time=clock.elapsedTime;update(dt,time);renderer.render(scene,camera)}
// Initial cinematic framing
camera.position.set(0,7.2,18);camera.lookAt(0,1.4,0);
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7))});
$('#loading').style.opacity='0';setTimeout(()=>$('#loading').remove(),550);frame();
</script>
</body>

